def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # A 3x3 ring with a 2 center emits a ray perpendicular to the 2 rail.
    centers = []
    for r in range(1, h-1):
        for c in range(1, w-1):
            if g[r][c] == 2 and all(g[rr][cc] == 3 for rr,cc in
                [(r-1,c-1),(r-1,c),(r-1,c+1),(r,c-1),(r,c+1),(r+1,c-1),(r+1,c),(r+1,c+1)]):
                centers.append((r,c))
    for r,c in centers:
        row_rail = sum(1 for x in range(w) if g[r][x] == 2) >= w//2
        col_rail = sum(1 for y in range(h) if g[y][c] == 2) >= h//2
        if row_rail and not col_rail:
            # Emit away from the ring to the lower edge, matching the open direction of the rail.
            for y in range(r+2, h):
                if g[y][c] == 0: g[y][c] = 1
                elif g[y][c] == 2:
                    if c > 0 and g[y][c-1] == 0: g[y][c-1] = 1
                    if c+1 < w and g[y][c+1] == 0: g[y][c+1] = 1
        elif col_rail and not row_rail:
            # Emit horizontally from the ring on both sides, preserving the 2 lattice.
            for x in range(c-2, -1, -1):
                if g[r][x] == 0: g[r][x] = 1
                elif g[r][x] == 2:
                    if r > 0 and g[r-1][x] == 0: g[r-1][x] = 1
                    if r+1 < h and g[r+1][x] == 0: g[r+1][x] = 1
            for x in range(c+2, w):
                if g[r][x] == 0: g[r][x] = 1
                elif g[r][x] == 2:
                    if r > 0 and g[r-1][x] == 0: g[r-1][x] = 1
                    if r+1 < h and g[r+1][x] == 0: g[r+1][x] = 1
    return g
