def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    rings = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr, cc in ((r-1,c-1),(r-1,c),(r-1,c+1),
                               (r,c-1),(r,c+1),
                               (r+1,c-1),(r+1,c),(r+1,c+1))
            ):
                rings.append((r, c))

    for r, c in rings:
        vertical_count = sum(grid[y][c] == 2 for y in range(h))
        horizontal_count = sum(grid[r][x] == 2 for x in range(w))
        if vertical_count > horizontal_count:
            # A symbol on a vertical rail emits a horizontal beam across its row.
            for x in range(w):
                if grid[r][x] == 0:
                    out[r][x] = 1
            # Each other 2 crossed by the beam creates a 3x3 flare.
            for x in range(w):
                if x == c or grid[r][x] != 2:
                    continue
                for yy in range(r-1, r+2):
                    for xx in range(x-1, x+2):
                        if (yy, xx) == (r, x):
                            continue
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 3:
                            out[yy][xx] = 1
        else:
            # A symbol on a horizontal rail emits perpendicular toward the nearest other rail.
            rails = [y for y in range(h) if y != r and sum(grid[y][x] == 2 for x in range(w)) > w // 2]
            if rails:
                nearest = min(rails, key=lambda y: abs(y-r))
                step = 1 if nearest > r else -1
            else:
                step = 1 if r < h // 2 else -1
            y = r + 2 * step
            while 0 <= y < h:
                if grid[y][c] == 2:
                    for yy in range(y-1, y+2):
                        for xx in range(c-1, c+2):
                            if (yy, xx) == (y, c):
                                continue
                            if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 3:
                                out[yy][xx] = 1
                elif grid[y][c] == 0:
                    out[y][c] = 1
                y += step
    return out
